# Surah Al-A'raf (chapter 7) — part 13: ayat 125-134 (IDs 1079-1088)
SURAH = 7

ENTRIES = {
1079: (
"جادوگروں نے کہا — بے شک — ہم — اپنے رب — کی طرف لوٹنے والے ہیں",
"""۱۔ جادوگروں کا — عاجزی کا جواب۔
۲۔ ’’قَالُوا إِنَّا إِلَىٰ رَبِّنَا مُنقَلِبُونَ‘‘ — جادوگروں نے کہا — بے شک — ہم — اپنے رب — کی طرف لوٹنے والے ہیں — یعنی جادوگر — موت کی پروا نہ کرتے ہوئے — ایمان پر قائم رہتے ہیں۔
۳۔ عملی سبق: موت — اللہ کی طرف واپسی ہے — لہٰذا ایمان پر قائم رہو۔"""
),
1080: (
"اور — تو ہم سے — صرف اس بات کا انتقام لیتا ہے کہ ہم — اپنے رب کی آیات پر — ایمان لائے — جب وہ ہمارے پاس آئیں — اے ہمارے رب — ہم پر صبر — انڈیل دے — اور ہمیں مسلمان — بنا کر — وفات دے",
"""۱۔ جادوگر — اپنی محنت — اللہ سے — مانگتے ہیں۔
۲۔ ’’وَمَا تَنقِمُ مِنَّا إِلَّا أَنْ آمَنَّا بِآيَاتِ رَبِّنَا لَمَّا جَاءَتْنَا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ‘‘ — اور — تو ہم سے — صرف اس بات کا انتقام لیتا ہے کہ ہم — اپنے رب کی آیات پر — ایمان لائے — جب وہ ہمارے پاس آئیں — اے ہمارے رب — ہم پر صبر — انڈیل دے — اور ہمیں مسلمان — بنا کر — وفات دے — یعنی جادوگر — فرعون کی سزا کا خوف نہیں کرتے — صرف اللہ سے صبر مانگتے ہیں۔
۳۔ عملی سبق: ایمان — سزا کی پروا نہیں کرتا؛ صبر اللہ سے مانگو۔"""
),
1081: (
"اور — فرعون کے سرداروں نے کہا — کیا — تو — موسیٰؑ اور اس کی قوم — کو — رہنے دے رہا ہے — تاکہ وہ — زمین میں — فساد کریں — اور — تجھے اور تیرے معبودوں کو — چھوڑ دیں — فرعون — نے کہا — ہم — ان کے بیٹوں کو — قتل کریں گے — اور ان کی عورتوں کو زندہ رکھیں گے — اور — بے شک — ہم — ان پر — غالب ہیں",
"""۱۔ فرعون کا — ظالم منصوبہ — بنی اسرائیل کو کمزور کرنا۔
۲۔ ’’وَقَالَ الْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُ لِيُفْسِدُوا فِي الْأَرْضِ وَيَذَرَكَ وَآلِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَاءَهُمْ وَنَسْتَحْيِي نِسَاءَهُمْ وَإِنَّا فَوْقَهُمْ قَاهِرُونَ‘‘ — اور — فرعون کے سرداروں نے کہا — کیا — تو — موسیٰؑ اور اس کی قوم — کو — رہنے دے رہا ہے — تاکہ وہ — زمین میں — فساد کریں — اور — تجھے اور تیرے معبودوں کو — چھوڑ دیں — فرعون — نے کہا — ہم — ان کے بیٹوں کو — قتل کریں گے — اور ان کی عورتوں کو زندہ رکھیں گے — اور — بے شک — ہم — ان پر — غالب ہیں — یعنی فرعون — اپنی طاقت کے نشے میں — بنی اسرائیل کو ختم کرنا چاہتا ہے۔
۳۔ عملی سبق: ظالمانہ منصوبے — ہمیشہ — ناکام ہوتے ہیں۔"""
),
1082: (
"موسیٰؑ نے — اپنی قوم سے کہا — اللہ سے — مدد مانگو — اور صبر کرو — بے شک — زمین — اللہ کی ہے — وہ — اس کا وارث — اپنے بندوں میں سے — جسے چاہے بناتا ہے — اور — انجام — متقیوں کا ہے",
"""۱۔ موسیٰؑ — اپنی قوم کو دو چیزیں سکھاتے ہیں: اللہ سے مدد اور صبر۔
۲۔ ’’قَالَ مُوسَىٰ لِقَوْمِهِ اسْتَعِينُوا بِاللَّهِ وَاصْبِرُوا إِنَّ الْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَاءُ مِنْ عِبَادِهِ وَالْعَاقِبَۃُ لِلْمُتَّقِينَ‘‘ — موسیٰؑ نے — اپنی قوم سے کہا — اللہ سے — مدد مانگو — اور صبر کرو — بے شک — زمین — اللہ کی ہے — وہ — اس کا وارث — اپنے بندوں میں سے — جسے چاہے بناتا ہے — اور — انجام — متقیوں کا ہے — یعنی فرعون کی طاقت کے سامنے — اللہ سے مدد اور صبر — ہی بنی اسرائیل کی راہ نجات ہے۔
۳۔ عملی سبق: مشکلات میں — اللہ سے مدد مانگو اور صبر کرو — انجام — متقیوں کا ہے۔"""
),
1083: (
"ان کی قوم نے کہا — ہمیں — اس سے پہلے بھی تکلیف دی گئی کہ تو ہمارے پاس آئے — اور — اس کے بعد بھی جو تو ہمارے پاس آئے — موسیٰؑ نے کہا — عنقریب — تمہارا رب — تمہارے دشمن کو — ہلاک کرے گا — اور — تمہیں — زمین میں — جانشین بنائے گا — پس — وہ دیکھے گا — کہ — تم — کیسے عمل کرتے ہو",
"""۱۔ بنی اسرائیل — تکلیف کی شکایت کرتے ہیں؛ موسیٰؑ امید دلاتے ہیں۔
۲۔ ’’قَالُوا أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِن بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِي الْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ‘‘ — ان کی قوم نے کہا — ہمیں — اس سے پہلے بھی تکلیف دی گئی کہ تو ہمارے پاس آئے — اور — اس کے بعد بھی جو تو ہمارے پاس آئے — موسیٰؑ نے کہا — عنقریب — تمہارا رب — تمہارے دشمن کو — ہلاک کرے گا — اور — تمہیں — زمین میں — جانشین بنائے گا — پس — وہ دیکھے گا — کہ — تم — کیسے عمل کرتے ہو — یعنی فرعون کا زوال — آ رہا ہے؛ بنی اسرائیل کو — زمین میں جانشینی ملے گی — مگر — امتحان ساتھ جاری رہے گا۔
۳۔ عملی سبق: تکلیف کے بعد — اللہ کی نصرت — آتی ہے — مگر اس کی آزمائش — بھی لازم ہے۔"""
),
1084: (
"اور — بے شک — ہم — نے — فرعون کے خاندان کو — سخت سالیوں — اور فصلوں کی کمی — سے — پکڑا — تاکہ — وہ — نصیحت حاصل کریں",
"""۱۔ فرعونی خاندان — قحط کی آزمائش۔
۲۔ ’’وَلَقَدْ أَخَذْنَا آلَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصٍ مِّنَ الثَّمَرَاتِ لَعَلَّهُمْ يَذَّكَّرُونَ‘‘ — اور — بے شک — ہم — نے — فرعون کے خاندان کو — سخت سالیوں — اور فصلوں کی کمی — سے — پکڑا — تاکہ — وہ — نصیحت حاصل کریں — یعنی اللہ — فرعون کو — قحط کے ذریعے — توبہ پر مجبور کرتا ہے۔
۳۔ عملی سبق: مصیبتیں — اللہ کی طرف — واپسی کا موقع ہوتی ہیں۔"""
),
1085: (
"پس — جب — انہیں — آسودگی آتی — تو کہتے — یہ — ہمارا حق ہے — اور — اگر — انہیں — کوئی برائی پہنچتی — تو — موسیٰؑ اور اس کے ساتھیوں پر — بری فال — لیتے — خبردار — ان کی بری فال — اللہ کے پاس ہے — لیکن — ان — میں سے اکثر — نہیں جانتے",
"""۱۔ فرعونی خاندان — خیر اور شر — دونوں کو — غلط نسبت دیتا ہے۔
۲۔ ’’فَإِذَا جَاءَتْهُمُ الْحَسَنَۃُ قَالُوا لَنَا هَٰذِهِ وَإِن تُصِبْهُمْ سَيِّئَۃٌ يَطَّيَّرُوا بِمُوسَىٰ وَمَن مَّعَهُ أَلَا إِنَّمَا طَائِرُهُمْ عِندَ اللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ‘‘ — پس — جب — انہیں — آسودگی آتی — تو کہتے — یہ — ہمارا حق ہے — اور — اگر — انہیں — کوئی برائی پہنچتی — تو — موسیٰؑ اور اس کے ساتھیوں پر — بری فال — لیتے — خبردار — ان کی بری فال — اللہ کے پاس ہے — لیکن — ان — میں سے اکثر — نہیں جانتے — یعنی فرعونی — خوش حالی کو اپنا حق سمجھتے اور — مصیبت کو موسیٰؑ کی نحوست — قرار دیتے ہیں۔
۳۔ عملی سبق: خیر و شر — اللہ کے پاس ہیں؛ کسی پر — الزام نہ ڈالو۔"""
),
1086: (
"اور انہوں نے کہا — جو بھی نشانی — تم — ہمیں — لاؤ — تاکہ — ہمیں — اس سے — جادو کرو — ہم — تمہارے — ایمان لانے والے — نہیں",
"""۱۔ فرعونی — ہر نشانی کو جادو قرار دیتے ہیں۔
۲۔ ’’وَقَالُوا مَهْمَا تَأْتِنَا بِهِ مِنْ آيَۃٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ‘‘ — اور انہوں نے کہا — جو بھی نشانی — تم — ہمیں — لاؤ — تاکہ — ہمیں — اس سے — جادو کرو — ہم — تمہارے — ایمان لانے والے — نہیں — یعنی فرعونی — پہلے ہی فیصلہ کر چکے تھے کہ — کوئی نشانی قبول نہ کریں گے۔
۳۔ عملی سبق: ضد — انسان کو — حق دیکھنے سے روک دیتی ہے۔"""
),
1087: (
"پس — ہم نے — ان پر — طوفان — ٹڈی دل — جوئیں — مینڈک — اور خون — الگ الگ نشانیوں کے طور پر — بھیجے — مگر — انہوں نے تکبر کیا — اور وہ — مجرم قوم تھے",
"""۱۔ فرعون پر — پانچ تباہ کن آفتیں۔
۲۔ ’’فَأَرْسَلْنَا عَلَيْهِمُ الطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ آيَاتٍ مُّفَصَّلَاتٍ فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا مُّجْرِمِينَ‘‘ — پس — ہم نے — ان پر — طوفان — ٹڈی دل — جوئیں — مینڈک — اور خون — الگ الگ نشانیوں کے طور پر — بھیجے — مگر — انہوں نے تکبر کیا — اور وہ — مجرم قوم تھے — یعنی اللہ — فرعون کو — مسلسل نشانوں سے — خبردار کرتا رہا۔
۳۔ عملی سبق: اللہ کی نشانیاں — لوگوں کو — ہوشیار رہنے کے لیے آتی ہیں۔"""
),
1088: (
"اور — جب — یہ عذاب ان پر — پڑا — تو وہ کہنے لگے — اے موسیٰؑ — اپنے رب سے — ہمارے لیے دعا کرو — اس — وعدے — کے مطابق — جو اس نے تمہارے ساتھ — کیا ہے — اگر — تو — ہم سے عذاب — دور کر دے — ہم — یقیناً — تجھ پر ایمان لائیں گے — اور — ہم — بنی اسرائیل کو — تیری ہم — کو — جانے دیں گے",
"""۱۔ فرعونی — مصیبت میں — توبہ اور وعدہ کرتے ہیں۔
۲۔ ’’وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُوا يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا الرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِي إِسْرَائِيلَ‘‘ — اور — جب — یہ عذاب ان پر — پڑا — تو وہ کہنے لگے — اے موسیٰؑ — اپنے رب سے — ہمارے لیے دعا کرو — اس — وعدے — کے مطابق — جو اس نے تمہارے ساتھ — کیا ہے — اگر — تو — ہم سے عذاب — دور کر دے — ہم — یقیناً — تجھ پر ایمان لائیں گے — اور — ہم — بنی اسرائیل کو — تیرے ساتھ — جانے دیں گے — یعنی فرعونی — مصیبت میں — عارضی طور پر — توبہ کا وعدہ کرتے ہیں۔
۳۔ عملی سبق: مصیبت میں وعدہ کرنا — اکثر عارضی ہوتا ہے؛ اپنے عہد پر قائم رہنا — اصل امتحان ہے۔"""
),
}
